describe('Password Reset Confirmation Message', () => {
  beforeEach(() => {
    cy.visit('/password-reset');
  });

  it('should display confirmation message after successful password reset', () => {
    // Intercept the password reset API call
    cy.intercept('POST', '/api/auth/reset-password').as('resetPassword');

    // Fill in the password reset form
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('NewPassword123!');
    cy.get('[data-testid="confirm-password-input"]').type('NewPassword123!');

    // Submit the form
    cy.get('[data-testid="reset-password-button"]').click();

    // Wait for the API call
    cy.wait('@resetPassword');

    // Verify success message is displayed
    cy.get('[data-testid="confirmation-message"]')
      .should('be.visible')
      .should('contain', 'Password successfully reset');

    // Verify success styling
    cy.get('[data-testid="confirmation-message"]')
      .should('have.class', 'success-message');

    // Verify form is cleared or disabled
    cy.get('[data-testid="email-input"]').should('have.value', '');
    cy.get('[data-testid="reset-password-button"]').should('be.disabled');
  });

  it('should not display confirmation message when password reset fails', () => {
    // Intercept the password reset API call and mock a failure response
    cy.intercept('POST', '/api/auth/reset-password', {
      statusCode: 400,
      body: { error: 'Email not found' }
    }).as('resetPasswordFailure');

    // Fill in the password reset form with invalid email
    cy.get('[data-testid="email-input"]').type('invalid-email@example.com');
    cy.get('[data-testid="password-input"]').type('Password123!');
    cy.get('[data-testid="confirm-password-input"]').type('Password123!');

    // Submit the form
    cy.get('[data-testid="reset-password-button"]').click();

    // Wait for the failed API call
    cy.wait('@resetPasswordFailure');

    // Verify error message is displayed instead of success message
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Email not found');

    // Verify success message does not appear
    cy.get('[data-testid="confirmation-message"]').should('not.exist');

    // Verify form is still enabled for retry
    cy.get('[data-testid="reset-password-button"]').should('not.be.disabled');
  });
});
